import * as React from "react";
import { cn } from "@/lib/utils";

export interface DialProps extends React.HTMLAttributes<HTMLDivElement> {
  value?: number;
  min?: number;
  max?: number;
  onChange?: (val: number) => void;
  label?: string;
  animationType?: 'radial-sweep' | 'magnetic-detent' | 'elastic-snap';
  inkColor?: string;
}

export const Dial: React.FC<DialProps> = ({ value = 65, min = 0, max = 100, onChange, label = 'Level', className, ...props }) => {
  return (
    <div className={cn("inline-flex flex-col items-center select-none font-mono text-xs", className)} {...props}>
      <div className="w-16 h-16 rounded-full border-2 border-dashed flex items-center justify-center font-bold">
        {Math.round(value)}
      </div>
      {label && <span className="text-[10px] mt-1 opacity-70">{label}</span>}
    </div>
  );
};
